(async () => {
  for (let i = 0; i < 250; i++) {
    const tabs = document.querySelectorAll('[data-testid^="tab-"]').length;
    const dims = document.querySelector('[data-testid="dims-label"]');
    const zoom = document.querySelector('[data-testid="zoom-label"]');
    const main = document.querySelector('.FIE_main-container');
    const spinner = document.querySelector('.FIE_spinner-wrapper');
    if (tabs === 6 && dims && zoom && main && !spinner && /^[0-9]+ x [0-9]+ px$/.test(dims.textContent.trim())) return true;
    await new Promise((r) => setTimeout(r, 100));
  }
  return false;
})()

